import React from 'react';
import {Page, Navbar, NavRight, Link} from 'framework7-react';
import { useTranslation } from 'react-i18next';
import { Device } from '../../../../../common/mobile/utils/device';
import SvgIcon from '@common/lib/component/SvgIcon';
import IconExpandDownIos from '@common-ios-icons/icon-expand-down.svg?ios';
import IconExpandDownAndroid from '@common-android-icons/icon-expand-down.svg';

const AddTable = props => {
    const { t } = useTranslation();
    const _t = t('View.Add', {returnObjects: true});
    const stylesList = props.stylesList || [];

    return (
        <Page>
            <Navbar title={_t.textStyle} backLink={_t.textBack}>
                {Device.phone &&
                    <NavRight>
                        <Link popupClose=".add-popup">
                            {Device.ios ?
                                <SvgIcon symbolId={IconExpandDownIos.id} className={'icon icon-svg'} /> :
                                <SvgIcon symbolId={IconExpandDownAndroid.id} className={'icon icon-svg'} />
                            }
                        </Link>
                    </NavRight>
                }
            </Navbar>
            <div className={'table-styles dataview'}>
                <ul className="row">
                    {stylesList.map((style, index) => (
                        <li key={index} onClick={() => props.onStyleSelect(style.name)}>
                            <img src={style.image} />
                        </li>
                    ))}
                </ul>
            </div>
        </Page>
    )
};

export default AddTable;
